#!/usr/bin/env python3\n\"\"\"\nDemo Scenarios Test Script\nValidates single-pass context resolution for NewsIQ demo scenarios.\n\"\"\"\n\nimport asyncio\nimport sys\nimport os\nimport time\nfrom typing import List, Dict, Any\n\n# Add project root to path\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n\nfrom main_orchestrator import orchestrator\nfrom intelligent_router import IntelligentRouter\n\nclass DemoTester:\n    def __init__(self):\n        self.router = IntelligentRouter()\n        self.results = []\n        self.thread_id = \"demo_test\"\n    \n    async def test_pronoun_resolution(self) -> Dict[str, Any]:\n        \"\"\"Test basic pronoun resolution scenarios.\"\"\"\n        print(\"\\n🧪 Testing Pronoun Resolution...\")\n        \n        scenarios = [\n            {\n                \"setup\": \"What is Trump doing?\",\n                \"followup\": \"What about his Epstein connection?\",\n                \"expected_entity\": \"Trump\",\n                \"expected_topic\": \"Epstein\"\n            },\n            {\n                \"setup\": \"Israel-Iran war updates\",\n                \"followup\": \"What about this conflict?\",\n                \"expected_entity\": \"Israel\",\n                \"expected_topic\": \"war\"\n            },\n            {\n                \"setup\": \"Compare Apple and Google\",\n                \"followup\": \"What about their AI ethics?\",\n                \"expected_entity\": \"Apple\",\n                \"expected_topic\": \"AI\"\n            }\n        ]\n        \n        results = []\n        for i, scenario in enumerate(scenarios):\n            print(f\"  Scenario {i+1}: {scenario['setup']} → {scenario['followup']}\")\n            \n            # Setup context\n            setup_result = await orchestrator.process_query(scenario['setup'], self.thread_id)\n            context_summary = setup_result.get('context_summary', '')\n            \n            # Test followup resolution\n            resolution = await self.router.resolve_intent_and_context(\n                scenario['followup'], context_summary\n            )\n            \n            # Validate resolution\n            resolved_query = resolution.resolved_query.lower()\n            has_entity = scenario['expected_entity'].lower() in resolved_query\n            has_topic = scenario['expected_topic'].lower() in resolved_query\n            confidence_ok = resolution.confidence >= 0.7\n            \n            result = {\n                \"scenario\": f\"{scenario['setup']} → {scenario['followup']}\",\n                \"resolved_query\": resolution.resolved_query,\n                \"confidence\": resolution.confidence,\n                \"has_entity\": has_entity,\n                \"has_topic\": has_topic,\n                \"confidence_ok\": confidence_ok,\n                \"success\": has_entity and confidence_ok\n            }\n            \n            results.append(result)\n            status = \"✅\" if result['success'] else \"❌\"\n            print(f\"    {status} Resolved: '{resolution.resolved_query}' (conf: {resolution.confidence:.2f})\")\n        \n        success_rate = sum(1 for r in results if r['success']) / len(results)\n        print(f\"  📊 Pronoun Resolution Success Rate: {success_rate:.1%}\")\n        \n        return {\n            \"test_name\": \"pronoun_resolution\",\n            \"success_rate\": success_rate,\n            \"results\": results\n        }\n    \n    async def test_multi_entity_conversation(self) -> Dict[str, Any]:\n        \"\"\"Test multi-turn conversation with entity tracking.\"\"\"\n        print(\"\\n🧪 Testing Multi-Entity Conversation...\")\n        \n        conversation = [\n            \"Israel-Iran war updates\",\n            \"What is India's stance?\", \n            \"How about Pakistan?\",\n            \"What about China's response?\"\n        ]\n        \n        results = []\n        context_summary = \"\"\n        \n        for i, query in enumerate(conversation):\n            print(f\"  Turn {i+1}: {query}\")\n            \n            if i == 0:\n                # First query - establish context\n                result = await orchestrator.process_query(query, self.thread_id)\n                context_summary = result.get('context_summary', '')\n                success = True  # First query always succeeds\n            else:\n                # Follow-up queries - test context resolution\n                resolution = await self.router.resolve_intent_and_context(query, context_summary)\n                context_summary = resolution.updated_summary\n                \n                # Check if resolution maintains context\n                resolved_lower = resolution.resolved_query.lower()\n                has_context = any(word in resolved_lower for word in ['israel', 'iran', 'war', 'conflict'])\n                confidence_ok = resolution.confidence >= 0.6  # Lower threshold for multi-turn\n                success = has_context and confidence_ok\n            \n            result = {\n                \"turn\": i + 1,\n                \"query\": query,\n                \"resolved_query\": resolution.resolved_query if i > 0 else query,\n                \"context_summary\": context_summary,\n                \"confidence\": resolution.confidence if i > 0 else 1.0,\n                \"success\": success\n            }\n            \n            results.append(result)\n            status = \"✅\" if success else \"❌\"\n            print(f\"    {status} Context: '{context_summary[:50]}...'\")\n        \n        success_rate = sum(1 for r in results if r['success']) / len(results)\n        print(f\"  📊 Multi-Entity Conversation Success Rate: {success_rate:.1%}\")\n        \n        return {\n            \"test_name\": \"multi_entity_conversation\",\n            \"success_rate\": success_rate,\n            \"results\": results\n        }\n    \n    async def test_semantic_drift_detection(self) -> Dict[str, Any]:\n        \"\"\"Test detection of topic changes (semantic drift).\"\"\"\n        print(\"\\n🧪 Testing Semantic Drift Detection...\")\n        \n        # Establish context then switch topics\n        setup_query = \"Latest Apple earnings report\"\n        drift_queries = [\n            \"What's the weather today?\",\n            \"How do I bake a cake?\",\n            \"Tell me about quantum physics\"\n        ]\n        \n        # Setup context\n        setup_result = await orchestrator.process_query(setup_query, self.thread_id)\n        context_summary = setup_result.get('context_summary', '')\n        print(f\"  Setup: {setup_query}\")\n        print(f\"  Context: '{context_summary}'\")\n        \n        results = []\n        for query in drift_queries:\n            print(f\"  Testing drift: {query}\")\n            \n            resolution = await self.router.resolve_intent_and_context(query, context_summary)\n            \n            # Should detect as NOT contextual follow-up\n            drift_detected = not resolution.is_contextual_follow_up\n            confidence_reasonable = resolution.confidence >= 0.5\n            \n            result = {\n                \"query\": query,\n                \"is_contextual_follow_up\": resolution.is_contextual_follow_up,\n                \"drift_detected\": drift_detected,\n                \"confidence\": resolution.confidence,\n                \"success\": drift_detected and confidence_reasonable\n            }\n            \n            results.append(result)\n            status = \"✅\" if result['success'] else \"❌\"\n            print(f\"    {status} Drift detected: {drift_detected} (conf: {resolution.confidence:.2f})\")\n        \n        success_rate = sum(1 for r in results if r['success']) / len(results)\n        print(f\"  📊 Semantic Drift Detection Success Rate: {success_rate:.1%}\")\n        \n        return {\n            \"test_name\": \"semantic_drift_detection\",\n            \"success_rate\": success_rate,\n            \"results\": results\n        }\n    \n    async def test_fallback_activation(self) -> Dict[str, Any]:\n        \"\"\"Test fallback safety activation.\"\"\"\n        print(\"\\n🧪 Testing Fallback Activation...\")\n        \n        # Test scenarios that should trigger fallback\n        ambiguous_queries = [\n            (\"Apple news\", \"What about it?\"),  # Ambiguous pronoun\n            (\"Multiple topics here\", \"That thing?\"),  # Vague reference\n            (\"\", \"Random query\")  # No context\n        ]\n        \n        results = []\n        for context_setup, query in ambiguous_queries:\n            print(f\"  Testing: '{query}' with context: '{context_setup}'\")\n            \n            resolution = await self.router.resolve_intent_and_context(query, context_setup)\n            \n            # Check if fallback was used (low confidence)\n            fallback_used = resolution.confidence < 0.7\n            has_resolved_query = bool(resolution.resolved_query.strip())\n            \n            result = {\n                \"query\": query,\n                \"context\": context_setup,\n                \"confidence\": resolution.confidence,\n                \"fallback_used\": fallback_used,\n                \"has_resolved_query\": has_resolved_query,\n                \"success\": has_resolved_query  # Should always have some query\n            }\n            \n            results.append(result)\n            status = \"✅\" if result['success'] else \"❌\"\n            fallback_status = \"(fallback)\" if fallback_used else \"(direct)\"\n            print(f\"    {status} Confidence: {resolution.confidence:.2f} {fallback_status}\")\n        \n        success_rate = sum(1 for r in results if r['success']) / len(results)\n        fallback_rate = sum(1 for r in results if r['fallback_used']) / len(results)\n        print(f\"  📊 Fallback Test Success Rate: {success_rate:.1%}\")\n        print(f\"  📊 Fallback Activation Rate: {fallback_rate:.1%}\")\n        \n        return {\n            \"test_name\": \"fallback_activation\",\n            \"success_rate\": success_rate,\n            \"fallback_rate\": fallback_rate,\n            \"results\": results\n        }\n    \n    async def run_all_tests(self) -> Dict[str, Any]:\n        \"\"\"Run all demo validation tests.\"\"\"\n        print(\"🚀 Starting NewsIQ Demo Validation Tests\\n\")\n        start_time = time.time()\n        \n        tests = [\n            self.test_pronoun_resolution(),\n            self.test_multi_entity_conversation(),\n            self.test_semantic_drift_detection(),\n            self.test_fallback_activation()\n        ]\n        \n        results = []\n        for test in tests:\n            try:\n                result = await test\n                results.append(result)\n            except Exception as e:\n                print(f\"❌ Test failed with error: {e}\")\n                results.append({\n                    \"test_name\": \"unknown\",\n                    \"success_rate\": 0.0,\n                    \"error\": str(e)\n                })\n        \n        # Calculate overall metrics\n        total_time = time.time() - start_time\n        overall_success = sum(r['success_rate'] for r in results) / len(results)\n        \n        print(f\"\\n📊 OVERALL RESULTS:\")\n        print(f\"  ⏱️  Total Test Time: {total_time:.1f}s\")\n        print(f\"  🎯 Overall Success Rate: {overall_success:.1%}\")\n        \n        for result in results:\n            test_name = result['test_name'].replace('_', ' ').title()\n            success_rate = result['success_rate']\n            status = \"✅\" if success_rate >= 0.8 else \"⚠️\" if success_rate >= 0.6 else \"❌\"\n            print(f\"  {status} {test_name}: {success_rate:.1%}\")\n        \n        # Demo readiness assessment\n        demo_ready = overall_success >= 0.8\n        print(f\"\\n🎭 DEMO READINESS: {'✅ READY' if demo_ready else '❌ NEEDS WORK'}\")\n        \n        return {\n            \"overall_success_rate\": overall_success,\n            \"total_time\": total_time,\n            \"demo_ready\": demo_ready,\n            \"test_results\": results\n        }\n\nasync def main():\n    \"\"\"Run demo validation tests.\"\"\"\n    tester = DemoTester()\n    results = await tester.run_all_tests()\n    \n    # Exit with appropriate code\n    exit_code = 0 if results['demo_ready'] else 1\n    sys.exit(exit_code)\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n